def merge_sorted(a, b):
    assert isinstance(a, list), "Input a must be a list"
    assert isinstance(b, list), "Input b must be a list"

    # Check if inputs are sorted
    for i in range(len(a) - 1):
        assert a[i] <= a[i+1], "List a is not sorted"
    for i in range(len(b) - 1):
        assert b[i] <= b[i+1], "List b is not sorted"

    # Handle empty lists
    if not a:
        return list(b)
    if not b:
        return list(a)

    merged = []
    i, j = 0, 0

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1

    # Append remaining elements
    while i < len(a):
        merged.append(a[i])
        i += 1

    while j < len(b):
        merged.append(b[j])
        j += 1

    return merged
